@startuml

class School {
  + name : string
}

class Person {
  + firstName : string
  + lastName : string
}

class Teacher extends Person {
  + email : string
}

class Student extends Person {}

class TeachingAssignment {
  + hours : int
}

class Room {
  + name : string
}

class Classroom extends Room {
  + capacity : int
}

class Gym extends Room {
  + size : float
}

class ClassGroup {
  + name : string
}

School "1" -- "1" Teacher : principal
School "1" -- "0..3" Teacher : employs
Teacher "1" -- "0..3" School : teaches
Teacher "1" -- "0..*" TeachingAssignment
School "1" -- "0..*" TeachingAssignment
TeachingAssignment "0..*" -- "1" School

School "1" -- "0..*" Room

Student "1" -- "1" ClassGroup
ClassGroup "1" -- "1" Classroom
ClassGroup "10..31" -- "1" Student

@enduml

